	VPL_Parameter _HiWord_1 = { kLongType,4,NULL,0,0,NULL};
	VPL_ExtProcedure _HiWord_F = {"HiWord",VPL_HiWord,&_HiWord_1,&_HiWord_R};

short VPL_LoWord(long input);
