void CGEventSetTimestampToNow( CGEventRef theEvent );
void CGEventSetTimestampToNow( CGEventRef theEvent )
{
	CGEventSetTimestamp( theEvent, (CGEventTimestamp)UnsignedWideToUInt64(UpTime()) );
}

	VPL_Parameter _CGEventSetTimestampToNow_1 = { kPointerType,0,"__CGEvent",1,0,NULL };
	VPL_ExtProcedure _CGEventSetTimestampToNow_F = {"CGEventSetTimestampToNow",CGEventSetTimestampToNow,&_CGEventSetTimestampToNow_1,NULL};


